describe('TA-Lib 0.8.3 compatibility', () => {
  for (const dataset of DATASETS) {
    const bars = readCsv(join(__dirname, dataset.file));

    describe(dataset.name, () => {
      for (const testCase of CASES) {
        it(`should match TA-Lib for ${testCase.name}`, () => {
          const results = testCase.compute(bars);
          expect(results.length).toBe(testCase.columns.length);

          testCase.columns.forEach((column, index) => {
            const expected = bars[column];
            expect(expected, `missing column ${column}`).toBeDefined();
            assertMatchesTalib(
              column,
              results[index],
              expected,
              testCase.scale,
              testCase.fromBar,
              testCase.hasWarmupValues
            );
          });
        });
      }
    });
  }
});
